// Resolve the client's rate card. Prefer client_config.rate_card passed by the
// orchestrator; otherwise fall back to the demo map (mirrors example_client_config.json).
// Production loads the client's signed-off rate card by client_id.
const trig = $('Execute Workflow Trigger').first().json;
const cfg = trig.client_config || {};
const DEMO_RATE_CARDS = {
  demo_client: {
    rate_by_category: { engineering: 85, assembly: 55, commissioning: 70, project_management: 95 },
    margin_pct: 0.20, risk_pct: 0.08, discount_pct: 0.0,
    payment_terms: '30% advance / 40% on delivery / 30% on commissioning', currency: 'EUR'
  }
};
const rate_card = cfg.rate_card || DEMO_RATE_CARDS[trig.client_id];
if (!rate_card) throw new Error(`No rate card available for client_id='${trig.client_id}'. Provide client_config.rate_card or add it to the demo map.`);
return [{ json: { client_id: trig.client_id, client_config: cfg, data: trig.data, rate_card } }];
